/// <summary>
/// PaffH 23.12.22
/// </summary>
/// <param name="_sender">FormDataSource</param>
/// <param name="_e">FormDataSourceEventArgs</param>
[FormDataSourceEventHandler(formDataSourceStr(ProdTable, ProdTable), FormDataSourceEventType::Activated),
    SuppressBPWarning('BPParameterNotUsed','Parameter is not used'),
    SuppressBPWarning('BPUpgradeCodeLateBoundCall','no way found to eliminate BP')]
public static void ProdTable_OnActivated(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    FormRun formRun = _sender.formRun();
    if (formHasMethod(formRun, formMethodStr(ProdTable, getPAInfo)))
    {
        formRun.getPAInfo();
    }
}
